import { TriangleAlert } from 'lucide-react-native';
import { View } from 'react-native';

import { Button } from '@/components/ui/button';
import { Icon } from '@/components/ui/icon';
import { Text } from '@/components/ui/text';

export function ErrorState({
  title,
  description,
  onRetry,
  retryLabel = 'Retry',
}: {
  title: string;
  description?: string;
  onRetry?: () => void;
  retryLabel?: string;
}) {
  return (
    <View className="flex-1 items-center justify-center gap-3 px-8 py-12">
      <Icon as={TriangleAlert} className="text-destructive" size={40} />
      <Text className="text-center text-xl font-semibold">{title}</Text>
      {description ? (
        <Text variant="muted" className="text-center">
          {description}
        </Text>
      ) : null}
      {onRetry ? (
        <Button variant="outline" size="sm" onPress={onRetry} className="mt-2">
          <Text>{retryLabel}</Text>
        </Button>
      ) : null}
    </View>
  );
}
